"""Render the neovim theme format from shared colors."""


def neovim_palette(colors: dict[str, str], ansi: list[str]) -> str:
    """Render the semantic Lua palette used by the colorscheme and local UI."""
    lines = [
        "-- Generated by iris-nocturne/build.py; "
        "edit palette.json in that project.",
        "return {",
    ]
    lines.extend(f'  ["{key}"] = "{value}",' for key, value in colors.items())
    lines.append("  ansi = {")
    lines.extend(f'    "{value}",' for value in ansi)
    lines.extend(["  },", "}"])
    return "\n".join(lines) + "\n"

